import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/getting-started.md","filePath":"ko-KR/user-guide/getting-started.md","lastUpdated":1787551561000}'),d={name:"ko-KR/user-guide/getting-started.md"};function n(s,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="시작하기" tabindex="-1">시작하기 <a class="header-anchor" href="#시작하기" aria-label="Permalink to &quot;시작하기&quot;">​</a></h1><h2 id="설치하기" tabindex="-1">설치하기 <a class="header-anchor" href="#설치하기" aria-label="Permalink to &quot;설치하기&quot;">​</a></h2><p>홈페이지의 <a href="./../">다운로드 버튼</a>에서 최신 릴리스를 받으세요 — 릴리스마다 두 가지 형태로 제공됩니다.</p><ul><li><strong>설치 프로그램</strong> (<code>Lertaro-Setup.exe</code>) — 권장 방식입니다. 백그라운드 인덱싱 서비스를 등록하며 Windows와 함께 Lertaro를 시작하도록 설정할 수 있습니다.</li><li><strong>포터블</strong> (<code>Lertaro-Portable.zip</code>) — 압축을 풀고 실행하기만 하면 되며, 설치 과정이 없습니다. 백그라운드 서비스는 나중에 <strong>설정 → 서비스 상태</strong>에서도 설치할 수 있습니다. 사용 중인 컴퓨터에 Lertaro가 필요로 하는 .NET Desktop Runtime이 아직 없다면, 함께 제공되는 <code>install-dotnet-runtime.bat</code>를 한 번 실행하세요 — 설치 프로그램은 이 단계를 자동으로 처리하지만, 포터블 빌드는 그럴 수 없습니다. 포터블 설치를 다 사용한 뒤에는 정리해 줄 제거 프로그램이 없습니다. 폴더를 삭제하기 전에 함께 제공되는 <code>portable-cleanup.bat</code>를 실행하세요. 서비스가 설치되어 있으면 Lertaro 백그라운드 서비스를 중지하고 제거하며, 현재 사용자에게 등록된 <code>lertaro://</code> URI 프로토콜과 &quot;Windows와 함께 시작&quot; 항목도 제거합니다. 서비스 제거 시 관리자 권한 확인이 표시될 수 있으며, 나머지 정리는 현재 사용자에 대해 수행됩니다.</li></ul><p>두 형태 모두 <strong>x64</strong> 빌드와 <strong>ARM64</strong> 빌드로 제공됩니다. 위의 이름은 x64 빌드이며, 최근의 PC라면 어디서든 실행됩니다 — Windows on ARM에서도 에뮬레이션으로 실행됩니다. ARM 기기에서는 네이티브로 동작하는 <code>Lertaro-Setup-arm64.exe</code> 또는 <code>Lertaro-Portable-arm64.zip</code>을 사용하세요. 자동 업데이트는 설치할 때의 아키텍처를 그대로 유지하므로, 다른 쪽으로 옮기려면 직접 내려받아야 합니다.</p><h2 id="휴대용-데이터" tabindex="-1">휴대용 데이터 <a class="header-anchor" href="#휴대용-데이터" aria-label="Permalink to &quot;휴대용 데이터&quot;">​</a></h2><p>휴대용 버전은 애플리케이션 옆의 <code>Data\\Machine</code>에 컴퓨터 데이터를, <code>Data\\Users\\&lt;SID hash&gt;</code>에 각 사용자의 개인 데이터를 저장합니다. <code>Data</code> 폴더가 아직 없으면 호환성을 위해 기존 <code>%ProgramData%\\Lertaro</code> 및 <code>%LocalAppData%\\Lertaro</code> 데이터를 재사용합니다. <code>Data</code>를 만들면 이 휴대용 복사본이 자체 데이터를 우선하여 독립적으로 동작합니다.</p><p>처음 실행하면, Lertaro는 파일 인덱싱을 담당하는 Windows 서비스(<code>Lertaro.Service</code>)를 설치하고 시작합니다. 이렇게 분리한 것은 의도적인 설계입니다 — 그 이유가 궁금하다면 <a href="./../dev-guide/architecture.html">아키텍처</a>를 참고하세요 — 하지만 사용자로서 알아야 할 것은 하나뿐입니다. <strong>설정 → 서비스 상태</strong>에서 서비스가 설치되어 실행 중인지 알려주며, 설치되어 있지 않다면 그곳에서 설치할 수 있습니다.</p><h2 id="세-가지-창" tabindex="-1">세 가지 창 <a class="header-anchor" href="#세-가지-창" aria-label="Permalink to &quot;세 가지 창&quot;">​</a></h2><p>Lertaro에는 검색 창이 하나만 있는 것이 아닙니다 — 사용 방식에 맞게 적응합니다.</p><ul><li><strong>메인 창</strong> — 작업 표시줄/시작 메뉴 바로가기에서 얻는 전체 창으로, 가장 큰 결과 목록과 창 내 Actions 패널을 갖고 있습니다.</li><li><strong>퀵 창</strong> — 전역 토글 단축키(기본값은 <code>Ctrl</code> 두 번 누르기)로 불러오는, 항상 위에 떠 있는 소형 팝업입니다. &quot;단축키 누르기 → 입력 → Enter&quot;라는 근육 기억을 위해 만들어졌습니다.</li><li><strong>인라인 창</strong> — 지원되는 네이티브 파일 대화상자나 파일 탐색기 창 안에 Lertaro 검색창을 직접 내장하여, 이미 열려 있는 대화상자를 벗어나지 않고도 검색할 수 있게 합니다.</li></ul><p>세 창 모두 동일한 검색 엔진, 단축키 시스템, Actions 메뉴를 공유합니다 — 차이는 순전히 어디에, 어떻게 나타나는지에 있습니다.</p><h2 id="기본-검색" tabindex="-1">기본 검색 <a class="header-anchor" href="#기본-검색" aria-label="Permalink to &quot;기본 검색&quot;">​</a></h2><p>최근 파일, 즐겨찾기, 기록은 아무것도 입력하지 않고도 꺼내 쓸 수 있습니다 — 모두 <a href="./settings/quick-panel.html">빠른 패널</a>의 탭이며, 이 패널은 검색 창 안이 아니라 앞에 있는 창 위에 열립니다.</p><p>그냥 입력을 시작하세요. 입력하는 대로 결과가 관련성 순으로 갱신됩니다(매칭과 순위가 어떻게 동작하는지는 <a href="./search-syntax.html">검색 문법</a> 참고). <a href="./hotkeys.html">설정 가능한 다음/이전 항목 단축키</a>(기본값은 화살표 키)로 선택을 이동하고, Enter로 강조된 결과를 여세요.</p><p>다음 단계: 쿼리 상자를 최대한 활용하려면 <a href="./search-syntax.html">검색 문법</a>을 확인하세요.</p>',16)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
